create table workspaces(id uuid primary key default gen_random_uuid(),name text,waba_id text,phone_number_id text,display_phone text,access_token text,created_at timestamptz default now());
create table members(workspace_id uuid references workspaces on delete cascade,user_id uuid references auth.users,role text check(role in('owner','admin','agent')) default 'agent',primary key(workspace_id,user_id));
create table contacts(id uuid primary key default gen_random_uuid(),workspace_id uuid references workspaces on delete cascade,phone text,name text,tags text[] default '{}',opted_in boolean default true,last_inbound_at timestamptz,assigned_to uuid,created_at timestamptz default now(),unique(workspace_id,phone));
create table templates(id uuid primary key default gen_random_uuid(),workspace_id uuid references workspaces on delete cascade,meta_id text,name text,language text,category text,status text,components jsonb,unique(workspace_id,name,language));
create table messages(id uuid primary key default gen_random_uuid(),workspace_id uuid references workspaces on delete cascade,contact_id uuid references contacts on delete cascade,wamid text unique,direction text,type text,body text,status text default 'queued',broadcast_id uuid,created_at timestamptz default now());
create table broadcasts(id uuid primary key default gen_random_uuid(),workspace_id uuid references workspaces on delete cascade,name text,template_name text,language text,tag text,scheduled_at timestamptz,status text default 'draft',created_at timestamptz default now());
create table automations(id uuid primary key default gen_random_uuid(),workspace_id uuid references workspaces on delete cascade,kind text check(kind in('keyword','welcome','drip')),keyword text,reply text,template_name text,delay_hours int default 0,active boolean default true);
create table drip_queue(id uuid primary key default gen_random_uuid(),automation_id uuid references automations on delete cascade,contact_id uuid references contacts on delete cascade,run_at timestamptz,done boolean default false);
alter table workspaces enable row level security;alter table contacts enable row level security;alter table messages enable row level security;alter table templates enable row level security;alter table broadcasts enable row level security;alter table automations enable row level security;alter table members enable row level security;
create policy m on members for select using(user_id=auth.uid());
create policy w on workspaces for all using(id in(select workspace_id from members where user_id=auth.uid()));
do $$ declare t text; begin foreach t in array array['contacts','messages','templates','broadcasts','automations'] loop execute format('create policy ws on %I for all using(workspace_id in(select workspace_id from members where user_id=auth.uid()))',t); end loop; end $$;
